create table if not exists public.crm_lead_sources(id uuid primary key default gen_random_uuid(),name text not null unique,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.crm_lead_statuses(id uuid primary key default gen_random_uuid(),name text not null unique,is_active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now());
insert into public.crm_lead_sources(name) values('WhatsApp'),('Instagram Message'),('Instagram Ad'),('Website'),('Phone Call'),('Referral'),('Walk-in'),('Other') on conflict(name) do nothing;
insert into public.crm_lead_statuses(name,sort_order) values('New',1),('Contacted',2),('No Response',3),('Follow-up',4),('Initial Assessment Scheduled',5),('Initial Assessment Done',6),('Paid Session Fixed',7),('Paid Session Done',8),('Closed',9),('Disqualified',10) on conflict(name) do nothing;
create table if not exists public.crm_leads(id uuid primary key default gen_random_uuid(),lead_date date not null default current_date,full_name text not null,phone text not null,gender text,profession text,reason_for_enquiry text,location text,source_id uuid references public.crm_lead_sources(id),status_id uuid references public.crm_lead_statuses(id),temperature text not null default 'cold' check(temperature in ('cold','warm','hot')),remarks text,assigned_to uuid references public.profiles(id),created_by uuid references public.profiles(id),archived_at timestamptz,converted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.crm_lead_followups(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.crm_leads(id) on delete cascade,follow_up_at timestamptz not null,note text,outcome text,next_follow_up_at timestamptz,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.crm_sales(id uuid primary key default gen_random_uuid(),lead_id uuid not null unique references public.crm_leads(id),closing_date date not null default current_date,sale_value numeric(12,2) not null default 0,currency text not null default 'INR',service_details text,first_session_date date,second_session_date date,third_session_date date,notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.crm_import_batches(id uuid primary key default gen_random_uuid(),file_name text not null,sheet_name text,imported_by uuid references public.profiles(id),imported_count integer not null default 0,skipped_count integer not null default 0,duplicate_count integer not null default 0,failed_count integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.crm_import_rows(id uuid primary key default gen_random_uuid(),batch_id uuid not null references public.crm_import_batches(id) on delete cascade,row_number integer not null,raw_data jsonb not null,result text not null,reason text,lead_id uuid references public.crm_leads(id),created_at timestamptz not null default now());
create index if not exists crm_leads_phone_idx on public.crm_leads(phone);create index if not exists crm_leads_assigned_idx on public.crm_leads(assigned_to,status_id);create index if not exists crm_followups_due_idx on public.crm_lead_followups(next_follow_up_at);create index if not exists crm_sales_closing_idx on public.crm_sales(closing_date);
create or replace function public.crm_can_manage(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_management() or (public.current_role()='general_manager' and public.in_management_tree(target)) $$;
alter table public.crm_leads enable row level security;alter table public.crm_lead_followups enable row level security;alter table public.crm_sales enable row level security;alter table public.crm_lead_sources enable row level security;alter table public.crm_lead_statuses enable row level security;alter table public.crm_import_batches enable row level security;alter table public.crm_import_rows enable row level security;
create policy "crm leads access" on public.crm_leads for all to authenticated using(assigned_to=auth.uid() or public.crm_can_manage(assigned_to)) with check(assigned_to=auth.uid() or public.crm_can_manage(assigned_to));create policy "crm followups access" on public.crm_lead_followups for all to authenticated using(exists(select 1 from public.crm_leads l where l.id=lead_id and (l.assigned_to=auth.uid() or public.crm_can_manage(l.assigned_to)))) with check(exists(select 1 from public.crm_leads l where l.id=lead_id and (l.assigned_to=auth.uid() or public.crm_can_manage(l.assigned_to))));create policy "crm sales access" on public.crm_sales for all to authenticated using(exists(select 1 from public.crm_leads l where l.id=lead_id and public.crm_can_manage(l.assigned_to))) with check(exists(select 1 from public.crm_leads l where l.id=lead_id and public.crm_can_manage(l.assigned_to)));create policy "crm config read" on public.crm_lead_sources for select to authenticated using(true);create policy "crm status read" on public.crm_lead_statuses for select to authenticated using(true);create policy "crm import management" on public.crm_import_batches for all to authenticated using(public.is_management()) with check(public.is_management());create policy "crm import rows management" on public.crm_import_rows for all to authenticated using(public.is_management()) with check(public.is_management());
